-- Dumping data for table `stories`
INSERT INTO `stories` (`id`, `author_id`, `story_title`, `person_name`, `profession`, `location`, `category`, `short_summary`, `full_story`, `show_name`, `status`, `views`, `ai_keywords`, `journey_map`) VALUES ('id_1788276343001_67hhjc0q2', NULL, 'Pioneering Clean Solar Microgrids for Rural Communities', 'Elena Rostova', 'Clean Energy Innovator & Researcher', 'Nairobi, Kenya', 'Innovation', 'How Elena built accessible off-grid solar energy systems that now power over 50,000 rural homes across East Africa.', 'Elena Rostova grew up in a rural village where electrical power outages lasted for days, severely disrupting evening study hours and healthcare clinic operations. From her early childhood in 2010, she harbored a deep dream to make clean, affordable energy accessible to every off-grid community in East Africa.\n\nAfter earning her doctorate in Renewable Energy Systems in 2018, Elena faced tremendous challenges: lack of early-stage venture funding, rugged terrain that hindered traditional infrastructure, and skepticism from legacy utility companies.\n\nThe pivotal turning point arrived in 2020 when Elena designed a decentralized solar microgrid powered by AI-optimized lithium battery management. Instead of relying on expensive centralized grids, her system allowed villagers to buy micro-shares of solar power via mobile payments.\n\nTaking decisive actions in 2021, Elena partnered with local youth, training over 200 young technicians to install and maintain the microgrids. Within three years, her startup successfully powered over 50,000 homes, 120 rural schools, and 45 community health clinics.\n\nHer key achievements include winning the Global CleanTech Innovation Award in 2023 and delivering uninterrupted light to over 250,000 citizens. Elena believes the key lesson is that sustainable technology succeeds only when built in true partnership with local communities. Looking toward her future vision, Elena aims to expand solar microgrid networks to cover 500,000 off-grid families by 2030.', 1, 'PUBLISHED', 5539, '["Elena","Solar","Rural","Power","Early","Energy","Grid","Community","When","Microgrid","Powered","Local"]', '{"title":"Pioneering Clean Solar Microgrids for Rural Communities","personName":"Elena Rostova","summary":"Elena Rostova grew up in a rural village where electrical power outages lasted for days, severely disrupting evening study hours and healthcare clinic operation...","category":"Success Story","heroImage":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=400&q=80","milestones":[{"stage":1,"title":"EARLY BACKGROUND","period":"2010","description":["Elena Rostova grew up in a rural village where electrical power outages lasted for days, severely disrupting evening study hours and healthcare cli...","From her early childhood in 2010, she harbored a deep dream to make clean, affordable energy accessible to every off-grid community in East Africa.","After earning her doctorate in Renewable Energy Systems in 2018, Elena faced tremendous challenges: lack of early-stage venture funding, rugged ter..."],"icon":"🌱","importance":"normal","categoryKey":"beginning","accentColor":"#10b981"},{"stage":2,"title":"IMPORTANT EVENTS","description":["Instead of relying on expensive centralized grids, her system allowed villagers to buy micro-shares of solar power via mobile payments."],"icon":"📅","importance":"normal","categoryKey":"importantEvents","accentColor":"#0284c7"},{"stage":3,"title":"TURNING POINT","period":"2020","description":["The pivotal turning point arrived in 2020 when Elena designed a decentralized solar microgrid powered by AI-optimized lithium battery management."],"icon":"🔄","importance":"high","categoryKey":"turningPoint","accentColor":"#8b5cf6"},{"stage":4,"title":"ACTIONS TAKEN","period":"2021","description":["Taking decisive actions in 2021, Elena partnered with local youth, training over 200 young technicians to install and maintain the microgrids."],"icon":"🚀","importance":"normal","categoryKey":"actions","accentColor":"#06b6d4"},{"stage":5,"title":"MAJOR ACHIEVEMENTS","period":"2023","description":["Her key achievements include winning the Global CleanTech Innovation Award in 2023 and delivering uninterrupted light to over 250,000 citizens.","Elena believes the key lesson is that sustainable technology succeeds only when built in true partnership with local communities."],"icon":"🏆","importance":"high","categoryKey":"achievements","accentColor":"#eab308"},{"stage":6,"title":"IMPACT CREATED","description":["Within three years, her startup successfully powered over 50,000 homes, 120 rural schools, and 45 community health clinics."],"icon":"🌍","importance":"normal","categoryKey":"impact","accentColor":"#10b981"},{"stage":7,"title":"FUTURE VISION","period":"2030","description":["Looking toward her future vision, Elena aims to expand solar microgrid networks to cover 500,000 off-grid families by 2030."],"icon":"🔮","importance":"normal","categoryKey":"futureVision","accentColor":"#d946ef"}],"achievements":[{"value":"2010","label":"KEY YEAR"},{"value":"2018","label":"KEY YEAR"},{"value":"2020","label":"KEY YEAR"},{"value":"2021","label":"KEY YEAR"}],"highlights":["Elena","Solar","Rural","Power","Early","Energy","Grid","Community","When","Microgrid"],"impact":"Within three years, her startup successfully powered over 50,000 homes, 120 rural schools, and 45 community health clinics.","futureVision":"Looking toward her future vision, Elena aims to expand solar microgrid networks to cover 500,000 off-grid families by 2030."}') ON DUPLICATE KEY UPDATE `story_title`='Pioneering Clean Solar Microgrids for Rural Communities';
INSERT INTO `stories` (`id`, `author_id`, `story_title`, `person_name`, `profession`, `location`, `category`, `short_summary`, `full_story`, `show_name`, `status`, `views`, `ai_keywords`, `journey_map`) VALUES ('id_1788276343004_h29nxd0ge', NULL, 'From High School Dropout to Tech Unicorn Founder', 'Carlos Mendoza', 'CEO & Co-founder, CodePulse', 'Austin, Texas', 'Entrepreneurship', 'Carlos overcame early financial hardship and multiple startup rejections to build an AI code review platform valued at $1.2B.', 'Carlos Mendoza was born in a working-class neighborhood where computer science education was virtually non-existent. Forced to drop out of high school at age 17 to support his family, Carlos taught himself software development during late-night shifts at a local library.\n\nHis early dream was simple: build software tools that help self-taught developers write bug-free code without requiring expensive engineering degrees. However, his journey was plagued by severe obstacles. His first two software startups failed completely, leaving him heavily in debt and working multiple freelance gigs to survive.\n\nThe turning point occurred when Carlos realized that artificial intelligence could automate complex software quality audits for small dev teams. Driven by determination, he spent 18 months coding the prototype for CodePulse in a small garage.\n\nThrough relentless execution, Carlos secured his first 1,000 paying users without any paid marketing. Fast forward five years, CodePulse raised its Series C funding round, scaling to 500 employees and reaching unicorn status with a $1.2 Billion valuation.\n\nCarlos has created over 800 tech jobs and established a $10M developer scholarship for underrepresented youth. His enduring lesson to aspiring founders is that failure is not the opposite of success, but an essential stepping stone towards it. His future vision is to establish 50 free coding academies across Latin America.', 1, 'PUBLISHED', 559, '["Carlos","Software","Working","Taught","Free","Without","First","Small","Coding","Codepulse","Mendoza","Born"]', '{"title":"From High School Dropout to Tech Unicorn Founder","personName":"Carlos Mendoza","summary":"Carlos Mendoza was born in a working-class neighborhood where computer science education was virtually non-existent. Forced to drop out of high school at age 17...","category":"Success Story","heroImage":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&q=80","milestones":[{"stage":1,"title":"EARLY BACKGROUND","description":["Carlos Mendoza was born in a working-class neighborhood where computer science education was virtually non-existent.","His early dream was simple: build software tools that help self-taught developers write bug-free code without requiring expensive engineering degrees."],"icon":"🌱","importance":"normal","categoryKey":"beginning","accentColor":"#10b981"},{"stage":2,"title":"CHALLENGES & STRUGGLES","description":["However, his journey was plagued by severe obstacles.","His enduring lesson to aspiring founders is that failure is not the opposite of success, but an essential stepping stone towards it."],"icon":"⚡","importance":"normal","categoryKey":"challenges","accentColor":"#f59e0b"},{"stage":3,"title":"IMPORTANT EVENTS","period":"AGE 17","description":["Forced to drop out of high school at age 17 to support his family, Carlos taught himself software development during late-night shifts at a local l...","His first two software startups failed completely, leaving him heavily in debt and working multiple freelance gigs to survive.","Driven by determination, he spent 18 months coding the prototype for CodePulse in a small garage."],"icon":"📅","importance":"normal","categoryKey":"importantEvents","accentColor":"#0284c7"},{"stage":4,"title":"TURNING POINT","description":["The turning point occurred when Carlos realized that artificial intelligence could automate complex software quality audits for small dev teams."],"icon":"🔄","importance":"high","categoryKey":"turningPoint","accentColor":"#8b5cf6"},{"stage":5,"title":"ACTIONS TAKEN","description":["Carlos has created over 800 tech jobs and established a $10M developer scholarship for underrepresented youth."],"icon":"🚀","importance":"normal","categoryKey":"actions","accentColor":"#06b6d4"},{"stage":6,"title":"FUTURE VISION","description":["His future vision is to establish 50 free coding academies across Latin America."],"icon":"🔮","importance":"normal","categoryKey":"futureVision","accentColor":"#d946ef"}],"achievements":[{"value":"17","label":"RURAL SCHOOLS"},{"value":"18","label":"MILESTONE"},{"value":"1,000","label":"ACTIVE USERS"},{"value":"500","label":"JOBS CREATED"}],"highlights":["Carlos","Software","Working","Taught","Free","Without","First","Small","Coding","Codepulse"],"impact":"","futureVision":"His future vision is to establish 50 free coding academies across Latin America."}') ON DUPLICATE KEY UPDATE `story_title`='From High School Dropout to Tech Unicorn Founder';
INSERT INTO `stories` (`id`, `author_id`, `story_title`, `person_name`, `profession`, `location`, `category`, `short_summary`, `full_story`, `show_name`, `status`, `views`, `ai_keywords`, `journey_map`) VALUES ('id_1788276343006_2rkkcg21k', NULL, 'Breaking Olympic Records in Distance Running', 'Elena Rostova', 'Olympic Marathon Gold Medalist', 'Zurich, Switzerland', 'Sports', 'Elena recovered from a career-threatening knee injury to win Olympic Gold and inspire millions of young female athletes worldwide.', 'Elena Rostova began distance running at age ten, discovering her natural endurance on the alpine trails of her home village. Her childhood dream was to stand atop the Olympic podium wearing her national colors.\n\nAt age 22, just one year before the World Championships, Elena suffered a devastating knee ligament tear during training. Doctors warned her that she might never sprint competitively again. The emotional hardship and physical pain tested her resilience to the absolute limit.\n\nHer turning point came during her eight-month intensive rehabilitation. Refusing to succumb to despair, Elena embraced a groundbreaking biomechanical recovery program paired with rigorous mental conditioning and swimming workouts.\n\nTaking disciplined action, Elena returned to competitive running, training 100 miles a week under extreme weather conditions. Her perseverance paid off when she broke the national marathon record and went on to claim the Olympic Gold Medal in Paris with a record-breaking time of 2:18:42.\n\nHer impact extends beyond sport: she launched the RunHer Foundation, providing athletic gear and coaching grants to young girls in underserved areas. Elena\'s core lesson is that true strength is forged in moments when giving up feels like the easiest option. Her future vision is to coach the next generation of Olympic champion runners.', 1, 'PUBLISHED', 1107, '["Elena","Olympic","Running","National","During","Training","When","Record","Rostova","Began","Distance","Discovering"]', '{"title":"Breaking Olympic Records in Distance Running","personName":"Elena Rostova","summary":"Elena Rostova began distance running at age ten, discovering her natural endurance on the alpine trails of her home village. Her childhood dream was to stand at...","category":"Success Story","heroImage":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=400&q=80","milestones":[{"stage":1,"title":"EARLY BACKGROUND","description":["Her childhood dream was to stand atop the Olympic podium wearing her national colors."],"icon":"🌱","importance":"normal","categoryKey":"beginning","accentColor":"#10b981"},{"stage":2,"title":"CHALLENGES & STRUGGLES","description":["The emotional hardship and physical pain tested her resilience to the absolute limit."],"icon":"⚡","importance":"normal","categoryKey":"challenges","accentColor":"#f59e0b"},{"stage":3,"title":"IMPORTANT EVENTS","period":"AGE 22","description":["Elena Rostova began distance running at age ten, discovering her natural endurance on the alpine trails of her home village.","At age 22, just one year before the World Championships, Elena suffered a devastating knee ligament tear during training.","Doctors warned her that she might never sprint competitively again."],"icon":"📅","importance":"normal","categoryKey":"importantEvents","accentColor":"#0284c7"},{"stage":4,"title":"TURNING POINT","description":["Her turning point came during her eight-month intensive rehabilitation."],"icon":"🔄","importance":"high","categoryKey":"turningPoint","accentColor":"#8b5cf6"},{"stage":5,"title":"ACTIONS TAKEN","description":["Taking disciplined action, Elena returned to competitive running, training 100 miles a week under extreme weather conditions."],"icon":"🚀","importance":"normal","categoryKey":"actions","accentColor":"#06b6d4"},{"stage":6,"title":"MAJOR ACHIEVEMENTS","description":["Her perseverance paid off when she broke the national marathon record and went on to claim the Olympic Gold Medal in Paris with a record-breaking t...","Her impact extends beyond sport: she launched the RunHer Foundation, providing athletic gear and coaching grants to young girls in underserved areas."],"icon":"🏆","importance":"high","categoryKey":"achievements","accentColor":"#eab308"},{"stage":7,"title":"LESSONS LEARNED","description":["Elena\'s core lesson is that true strength is forged in moments when giving up feels like the easiest option."],"icon":"💡","importance":"normal","categoryKey":"lessons","accentColor":"#e11d48"},{"stage":8,"title":"FUTURE VISION","description":["Her future vision is to coach the next generation of Olympic champion runners."],"icon":"🔮","importance":"normal","categoryKey":"futureVision","accentColor":"#d946ef"}],"achievements":[{"value":"22","label":"KEY YEAR"},{"value":"100","label":"MILESTONE"},{"value":"18","label":"RECORD / AWARD"},{"value":"42","label":"RECORD / AWARD"}],"highlights":["Elena","Olympic","Running","National","During","Training","When","Record","Rostova","Began"],"impact":"","futureVision":"Her future vision is to coach the next generation of Olympic champion runners."}') ON DUPLICATE KEY UPDATE `story_title`='Breaking Olympic Records in Distance Running';
INSERT INTO `stories` (`id`, `author_id`, `story_title`, `person_name`, `profession`, `location`, `category`, `short_summary`, `full_story`, `show_name`, `status`, `views`, `ai_keywords`, `journey_map`) VALUES ('id_1788276343281_q453f8ia4', NULL, 'Building Solar Power Infrastructure in Rural India', 'Kavita Patel', 'Inspiring Individual', 'Global', 'Innovation', 'Kavita Patel was raised in a small farming village in Gujarat where electricity was unavailable after sunset. In 2012, she set a personal goal to become an electrical engineer and ...', 'Kavita Patel was raised in a small farming village in Gujarat where electricity was unavailable after sunset. In 2012, she set a personal goal to become an electrical engineer and build decentralized renewable energy solutions for rural farmers.\n\nWhile attending university from 2014 to 2018, Kavita faced immense financial hurdles, taking night shifts at a call center while completing her engineering coursework.\n\nHer turning point came in 2019 when she engineered a low-cost micro-inverter that could connect individual solar panels directly to farm water pumps.\n\nIn 2021, Kavita founded SunKranti, hiring 30 local engineers and installing micro-inverters across 500 villages.\n\nBy 2023, SunKranti powered 15,000 farms, increased crop yield by 40%, and won the National Innovation Excellence Award.', 0, 'PUBLISHED', 14, '["Kavita","While","Micro","Sunkranti","2012","2014","2018","2019","2021","2023","Patel","Raised"]', '{"title":"Building Solar Power Infrastructure in Rural India","personName":"Kavita Patel","summary":"Kavita Patel was raised in a small farming village in Gujarat where electricity was unavailable after sunset. In 2012, she set a personal goal to become an elec...","category":"Innovation","heroImage":"","milestones":[{"stage":1,"title":"THE DREAM & GOAL","period":"2012","description":["In 2012, she set a personal goal to become an electrical engineer and build decentralized renewable energy solutions for rural farmers."],"icon":"🎯","importance":"normal","categoryKey":"goal","accentColor":"#6366f1"},{"stage":2,"title":"IMPORTANT EVENTS","period":"2014","description":["Kavita Patel was raised in a small farming village in Gujarat where electricity was unavailable after sunset.","While attending university from 2014 to 2018, Kavita faced immense financial hurdles, taking night shifts at a call center while completing her eng...","In 2021, Kavita founded SunKranti, hiring 30 local engineers and installing micro-inverters across 500 villages."],"icon":"📅","importance":"normal","categoryKey":"importantEvents","accentColor":"#0284c7"},{"stage":3,"title":"TURNING POINT","period":"2019","description":["Her turning point came in 2019 when she engineered a low-cost micro-inverter that could connect individual solar panels directly to farm water pumps."],"icon":"🔄","importance":"high","categoryKey":"turningPoint","accentColor":"#8b5cf6"},{"stage":4,"title":"MAJOR ACHIEVEMENTS","period":"2023","description":["By 2023, SunKranti powered 15,000 farms, increased crop yield by 40%, and won the National Innovation Excellence Award."],"icon":"🏆","importance":"high","categoryKey":"achievements","accentColor":"#eab308"}],"achievements":[{"value":"2012","label":"KEY YEAR"},{"value":"2014","label":"KEY YEAR"},{"value":"2018","label":"KEY YEAR"},{"value":"2019","label":"KEY YEAR"}],"highlights":["Kavita","While","Micro","Sunkranti","2012","2014","2018","2019","2021","2023"],"impact":"","futureVision":""}') ON DUPLICATE KEY UPDATE `story_title`='Building Solar Power Infrastructure in Rural India';
INSERT INTO `stories` (`id`, `author_id`, `story_title`, `person_name`, `profession`, `location`, `category`, `short_summary`, `full_story`, `show_name`, `status`, `views`, `ai_keywords`, `journey_map`) VALUES ('id_1788326132357_paqn4t4cj', NULL, 'success story', 'brightton', 'Inspiring Individual', 'Global', 'Innovation', 'Hi Everyone,\n\n*Message received from Chennai Group*\n\n*The Power of NEC Alumni ❤️*\n\nMy daughter recently got admission to BITS Goa. Initially, my wife and I were a little worried as...', 'Hi Everyone,\n\n*Message received from Chennai Group*\n\n*The Power of NEC Alumni ❤️*\n\nMy daughter recently got admission to BITS Goa. Initially, my wife and I were a little worried as we didn\'t know anyone in BITS or Goa.\n\nFortunately, *I reached out to our NEC Alumni group* , and I was amazed by the support and guidance I received from so many people. Now my daughter has started her journey at BITS Goa, and we both feel much more relaxed. 😊\n\nA special thanks to @Rajasekar Sir  Anna and @Mathiprakasam Anna for guiding me and introducing me to Subramanian Anna, an NEC alumnus who has been living in Goa for more than 20 years. He is also from my native place, Tenkasi. Despite his busy schedule as Chief GM of Goa Shipyard, he spent time with us and gave us great moral support.\n\nThanks also to @+91 95665 15746 , who introduced me to a Professor at BITS, which was very helpful.\n\nA big thanks to @Ajith 2019 CSE  , an alumnus of both NEC and BITS Goa, for sharing valuable insights and guidance.\n\nAnd special thanks to @Yogesh Karayalar 88 Batch CSE  Anna, our academic superhero, who guided us at the right time and helped us make an important decision.\n\nI feel truly blessed and proud to be part of the NEC Alumni family. ❤️\n\nThis is the real power of Alumni — supporting each other when it matters most.\n\n🙏 Thank you all for your support and guidance!', 0, 'PUBLISHED', 32, '["Bits","Alumni","Thanks","Anna","Support","Guidance","Received","Group","Power","Daughter","Both","Feel"]', '{"title":"success story","personName":"brightton","summary":"Hi Everyone,\\n\\n*Message received from Chennai Group*\\n\\n*The Power of NEC Alumni ❤️*\\n\\nMy daughter recently got admission to BITS Goa. Initially, my wife and I were...","category":"Innovation","heroImage":"","milestones":[{"stage":1,"title":"THE DREAM & GOAL","description":["Hi Everyone,\\n\\n*Message received from Chennai Group*\\n\\n*The Power of NEC Alumni ❤️*\\n\\nMy daughter recently got admission to BITS Goa."],"icon":"🎯","importance":"normal","categoryKey":"goal","accentColor":"#6366f1"},{"stage":2,"title":"IMPORTANT EVENTS","description":["Initially, my wife and I were a little worried as we didn\'t know anyone in BITS or Goa.","Fortunately, *I reached out to our NEC Alumni group* , and I was amazed by the support and guidance I received from so many people.","Now my daughter has started her journey at BITS Goa, and we both feel much more relaxed."],"icon":"📅","importance":"normal","categoryKey":"importantEvents","accentColor":"#0284c7"},{"stage":3,"title":"IMPACT CREATED","description":["And special thanks to @Yogesh Karayalar 88 Batch CSE  Anna, our academic superhero, who guided us at the right time and helped us make an important..."],"icon":"🌍","importance":"normal","categoryKey":"impact","accentColor":"#10b981"}],"achievements":[{"value":"20","label":"KEY YEAR"},{"value":"91","label":"MILESTONE"},{"value":"95665","label":"KEY YEAR"},{"value":"15746","label":"KEY YEAR"}],"highlights":["Bits","Alumni","Thanks","Anna","Support","Guidance","Received","Group","Power","Daughter"],"impact":"And special thanks to @Yogesh Karayalar 88 Batch CSE  Anna, our academic superhero, who guided us at the right time and helped us make an important decision.","futureVision":""}') ON DUPLICATE KEY UPDATE `story_title`='success story';
